def _evaluate(node, variables: dict):
    kind = node[0]
    if kind == "num":
        return node[1]
    if kind == "var":
        return variables[node[1]]
    if kind == "neg":
        return -_evaluate(node[1], variables)
    _, op, left_node, right_node = node
    left = _evaluate(left_node, variables)
    right = _evaluate(right_node, variables)
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if right == 0:
        raise ZeroDivisionError("division by zero")
    return left // right


